import Foundation

enum Operation: String { case add, subtract, multiply, divide }
enum CalculatorError: Error { case divisionByZero }

func calculate(_ left: Double, _ operation: Operation, _ right: Double) throws -> Double {
    switch operation {
    case .add: return left + right
    case .subtract: return left - right
    case .multiply: return left * right
    case .divide:
        guard right != 0 else { throw CalculatorError.divisionByZero }
        return left / right
    }
}

func parseNumber(_ text: String) -> Double? { Double(text.trimmingCharacters(in: .whitespacesAndNewlines)) }
print(try calculate(8, .divide, 2))
print(parseNumber("not a number") == nil ? "Invalid number handled" : "Unexpected input")
